define(['local_availabilityhelper/adapter/yui','local_availabilityhelper/analyzer','local_availabilityhelper/ui'],function(Adapter,Analyzer,UI){'use strict';
// This file is part of Moodle - http://moodle.org/

const connect = Adapter.connect;
const analyse = Analyzer.analyse;


let timer;

/**
 * Starts the availability helper when a core editor exists on the page.
 */
const init = () => {
    connect((tree, editor) => {
        window.clearTimeout(timer);
        timer = window.setTimeout(async() => {
            await UI.initialise(editor);
            UI.render(editor, analyse(tree));
        }, 350);
    });
};



return {init: init};
});
